using System;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Moq;
using Tsingtao.Redis.Extensions;
using Tsingtao.SDK.Weixin;
using Tsingtao.Supplier.Interfaces;
using Tsingtao.Supplier.Services;
using Tsingtao.Supplier.WebApi.Controllers;
using Tsingtao.Supplier.WebApi.Models.Pub;

namespace Tsingtao.UnitTests.Sdks
{
    [TestFixture]
    public class PubControllerTest
    {
        private Mock<IRedisClient> _redis;
        private Mock<IUserService> _userService;
        private Mock<ICaptchaService> _captchaService;
        private PubController _controller;

        [SetUp]
        public void SetUp()
        {
            var weixin = new WeixinCommonAPI(
                Options.Create(new WeixinOptions()),
                Mock.Of<ILoggerProvider>());

            var options = Options.Create(new SupplierOptions
            {
                Captcha = new SupplierCaptchaOptions
                {
                    DayMaxGenTimes = 10,
                    MaxGenInterval = 60,
                    CaptchaTemplate = "验证码：{0}"
                }
            });

            _redis = new Mock<IRedisClient>();
            _userService = new Mock<IUserService>();
            _captchaService = new Mock<ICaptchaService>();

            _controller = new PubController(
                weixin,
                new Mock<IOrganizationService>().Object,
                _captchaService.Object,
                options,
                new Mock<IRightService>().Object,
                _userService.Object,
                _redis.Object);
        }

        [Test]
        public void GetValidateCodeAsync_WhenWithinInterval_ReturnsIntervalError()
        {
            _redis
                .Setup(item => item.StringGetAsync(It.IsAny<string>()))
                .ReturnsAsync("1719000000");

            var result = _controller.GetValidateCodeAsync(CreateModel()).GetAwaiter().GetResult();

            Assert.That(result.Code, Is.EqualTo(ErrCodeEnum.Create_Captcha_300802));
            _redis.Verify(item => item.StringIncrementAsync(
                It.IsAny<string>(), It.IsAny<int>(), It.IsAny<TimeSpan?>()), Times.Never);
            _captchaService.Verify(item => item.CreateCaptchaAsync(It.IsAny<string>()), Times.Never);
        }

        [Test]
        public void GetValidateCodeAsync_WhenRequestIsValid_ReturnsSuccess()
        {
            _redis
                .Setup(item => item.StringGetAsync(It.IsAny<string>()))
                .ReturnsAsync((string)null);
            _redis
                .Setup(item => item.StringIncrementAsync(
                    It.IsAny<string>(), It.IsAny<int>(), It.IsAny<TimeSpan?>()))
                .ReturnsAsync(1);
            _redis
                .Setup(item => item.StringSetAsync(
                    It.IsAny<string>(), It.IsAny<string>(), It.IsAny<TimeSpan?>()))
                .ReturnsAsync(true);
            _userService
                .Setup(item => item.CheckLoginPhoneAsync("13800138000"))
                .ReturnsAsync(ErrCodeEnum.Success);
            _captchaService
                .Setup(item => item.CreateCaptchaAsync("13800138000"))
                .ReturnsAsync(Tuple.Create(ErrCodeEnum.Success, "654321"));
            _captchaService
                .Setup(item => item.DsmSenVerifyCode(
                    "13800138000", "验证码：654321", null))
                .ReturnsAsync(true);

            var result = _controller.GetValidateCodeAsync(CreateModel()).GetAwaiter().GetResult();

            Assert.That(result.Code, Is.EqualTo(ErrCodeEnum.Success));
            _userService.Verify(item => item.CheckLoginPhoneAsync("13800138000"), Times.Once);
            _captchaService.Verify(item => item.CreateCaptchaAsync("13800138000"), Times.Once);
            _captchaService.Verify(item => item.DsmSenVerifyCode(
                "13800138000", "验证码：654321", null), Times.Once);
        }

        private static SendMobileValidateCodeReqModel CreateModel()
        {
            return new SendMobileValidateCodeReqModel
            {
                Phone = "13800138000",
                VerifyType = VaidateCodeReqType.Login,
                Param = Array.Empty<string>()
            };
        }
    }
}

