using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Moq;
using Tsingtao.Redis.Extensions;
using Tsingtao.Supplier.Interfaces;

namespace Tsingtao.UnitTests.WebApi
{
    public class SupplierWebApplicationFactory : WebApplicationFactory<Tsingtao.Supplier.WebApi.Program>
    {
        public Mock<IRedisClient> RedisClient { get; } = new Mock<IRedisClient>();
        public Mock<ICaptchaService> CaptchaService { get; } = new Mock<ICaptchaService>();
        public Mock<IUserService> UserService { get; } = new Mock<IUserService>();
        public Mock<IOrganizationService> OrganizationService { get; } = new Mock<IOrganizationService>();
        public Mock<IRightService> RightService { get; } = new Mock<IRightService>();

        protected override void ConfigureWebHost(IWebHostBuilder builder)
        {
            builder.UseEnvironment("Testing");
            builder.ConfigureServices(services =>
            {
                Replace(services, RedisClient.Object);
                Replace(services, CaptchaService.Object);
                Replace(services, UserService.Object);
                Replace(services, OrganizationService.Object);
                Replace(services, RightService.Object);
            });
        }

        private static void Replace<TService>(IServiceCollection services, TService implementation)
            where TService : class
        {
            services.RemoveAll<TService>();
            services.AddSingleton(implementation);
        }
    }
}

