using System.Net;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace Tsingtao.UnitTests.WebApi
{
    [TestFixture]
    public class PubControllerIntegrationTest
    {
        private SupplierWebApplicationFactory _factory;
        private HttpClient _client;

        [SetUp]
        public void SetUp()
        {
            _factory = new SupplierWebApplicationFactory();
            _client = _factory.CreateClient();
        }

        [TearDown]
        public void TearDown()
        {
            _client.Dispose();
            _factory.Dispose();
        }

        [TestCase("", "手机号不能为空")]
        [TestCase("1380013800a", "手机号码格式不正确")]
        public async Task GetValidateCodeAsync_WhenPhoneIsInvalid_ReturnsValidationError(
            string phone, string expectedMessage)
        {
            var response = await _client.PostAsJsonAsync("/api/pub/getValidateCode", new
            {
                Phone = phone,
                VerifyType = 1,
                Param = Array.Empty<string>()
            });
            var result = JsonConvert.DeserializeObject<BaseResult>(
                await response.Content.ReadAsStringAsync());

            Assert.That(response.StatusCode, Is.EqualTo(HttpStatusCode.OK));
            Assert.That(result, Is.Not.Null);
            Assert.That(result.Code, Is.EqualTo(ErrCodeEnum.ParametersInvalid));
            Assert.That(result.Message, Is.EqualTo(expectedMessage));
            _factory.RedisClient.VerifyNoOtherCalls();
            _factory.UserService.VerifyNoOtherCalls();
            _factory.CaptchaService.VerifyNoOtherCalls();
        }
    }
}

