55	        public async Task<Tuple<ErrCodeEnum, string>> CreateCaptchaAsync(string phone)
56	        {
57	            var startTime = DateTime.Now.Date.ToLongUnixTimestamp();
58	            var endTime = DateTime.Now.AddDays(1).Date.ToLongUnixTimestamp();
59	            var captchaList = await _context.VerificationCodeList.CountAsync(q =>
60	                q.Target == phone && q.TargetType == CaptchaTarget.Phone &&
61	                q.SendTime > startTime &&
62	                q.SendTime < endTime);
63	
64	            if (captchaList > _options.Captcha.DayMaxGenTimes)
65	            {
66	                return Tuple.Create(ErrCodeEnum.Create_Captcha_300801, string.Empty);
67	            }
68	
69	            var maxCaptchaEntity = await _context.VerificationCodeList
70	                .Where(q => q.Target == phone && q.TargetType == CaptchaTarget.Phone)
71	                .OrderByDescending(q => q.SendTime).FirstOrDefaultAsync();
72	
73	            if (maxCaptchaEntity != null && maxCaptchaEntity.SendTime > DateTime.Now.AddSeconds(-_options.Captcha.MaxGenInterval).ToLongUnixTimestamp())
74	            {
75	                return Tuple.Create(ErrCodeEnum.Create_Captcha_300802, string.Empty);
76	            }
77	
78	            //将未使用状态记录置为作废
79	            await _context.Database.ExecuteSqlInterpolatedAsync($"UPDATE PUB_VERIFICATION_CODES SET STATUS=2 WHERE TARGET={phone} AND STATUS={CaptchaStatus.NotUsed}");
80	            await _context.SaveChangesAsync();
81	
82	            var code = GenRandomNumber();
83	
84	            // 将验证码写入表
85	            var verificationCodeEntity = new VerificationCodeEntity
86	            {
87	                Id = Guid.NewGuid().ToString(),
88	                SendTime = DateTime.Now.ToLongUnixTimestamp(),
89	                Status = CaptchaStatus.NotUsed,
90	                Source = _options.Captcha.Source,
91	                Code = code,
92	                Target = phone,
93	                TargetType = CaptchaTarget.Phone,
94	                ValidTime = DateTime.Now.AddSeconds(_options.Captcha.EffectiveDuration).ToLongUnixTimestamp()
95	            };
96	            await _context.VerificationCodeList.AddAsync(verificationCodeEntity);
97	            var count = await _context.SaveChangesAsync();
98	
99	            return count > 0
100	                ? Tuple.Create(ErrCodeEnum.Success, code)
101	                : Tuple.Create(ErrCodeEnum.Create_Captcha_300803, string.Empty);
102	        }
