using System;
using System.Collections.Generic;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.Extensions.Options;
using Moq;
using Tsingtao;
using Tsingtao.DigitalSeal.Datas;
using Tsingtao.DigitalSeal.Datas.Entities.Basic;
using Tsingtao.DigitalSeal.Enums.Basic;
using Tsingtao.Redis.Extensions;
using Tsingtao.SDK.DigitalSeal;
using Tsingtao.SDK.DigitalSeal.Captcha;
using Tsingtao.SDK.DigitalSeal.Msg;
using Tsingtao.Supplier.Services;

namespace Tsingtao.UnitTests.Services
{
    [TestFixture]
    public class CaptchaServiceTest
    {
        private const string Phone = "13800138000";
        private const string Code = "654321";
        private const string Source = "SUPPLIER_WECHART";

        private DbContextOptions<EsignDbContext> _dbOptions;
        private Mock<IRedisClient> _redis;
        private Mock<IHtmlHelper> _dummy;
        private CaptchaService _service;

        [SetUp]
        public void SetUp()
        {
            _dbOptions = new DbContextOptionsBuilder<EsignDbContext>()
                .UseInMemoryDatabase(Guid.NewGuid().ToString())
                .Options;

            _redis = new Mock<IRedisClient>();

            var options = Options.Create(new SupplierOptions
            {
                Captcha = new SupplierCaptchaOptions
                {
                    Source = Source,
                    DayMaxGenTimes = 10,
                    MaxGenInterval = 60,
                    EffectiveDuration = 900
                }
            });

            var request = new DigitalSealAPIRequest(
                new NullLoggerProvider(),
                Options.Create(new DigitalSealAPIOptions()));
            var captchaApi = new CaptchaApi(request);
            var msgApi = new MsgAPI(
                request,
                new NullLoggerProvider(),
                Options.Create(new MsgAPIOptions()));

            using var context = new EsignDbContext(_dbOptions);
            context.Database.EnsureCreated();

            _service = new CaptchaService(
                new EsignDbContext(_dbOptions),
                new NullLoggerProvider(),
                options,
                msgApi,
                captchaApi,
                _redis.Object,
                new HttpContextAccessor());
        }

        [Test]
        public async Task VerifyAsync_WhenLockPresent_ReturnsLocked()
        {
            _redis.Setup(r => r.StringGetAsync(It.IsAny<string>()))
                .ReturnsAsync("1719000000");

            var result = await _service.VerifyAsync(Code, Phone);

            Assert.That(result, Is.EqualTo(ErrCodeEnum.Verify_301002));
            _redis.Verify(r => r.StringIncrementAsync(It.IsAny<string>(), It.IsAny<int>(), It.IsAny<TimeSpan?>()), Times.Never);
        }

        [Test]
        public async Task VerifyAsync_WhenNoCaptcha_ReturnsVerifyFail()
        {
            _redis.Setup(r => r.StringGetAsync(It.IsAny<string>()))
                .ReturnsAsync((string)null);
            _redis.Setup(r => r.StringIncrementAsync(It.IsAny<string>(), It.IsAny<int>(), It.IsAny<TimeSpan?>()))
                .ReturnsAsync(1L);

            var result = await _service.VerifyAsync(Code, Phone);

            Assert.That(result, Is.EqualTo(ErrCodeEnum.Verify_301001));
        }

        [Test]
        public async Task VerifyAsync_WhenWrongCodeAndUnderThreshold_ReturnsCodeVerifyFail()
        {
            SeedValidCaptcha(Code);
            _redis.Setup(r => r.StringGetAsync(It.IsAny<string>()))
                .ReturnsAsync((string)null);
            _redis.Setup(r => r.StringIncrementAsync(It.IsAny<string>(), It.IsAny<int>(), It.IsAny<TimeSpan?>()))
                .ReturnsAsync(1L);

            var result = await _service.VerifyAsync("000000", Phone);

            Assert.That(result, Is.EqualTo(ErrCodeEnum.CodeVerifyFail));
            _redis.Verify(r => r.StringSetAsync(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<TimeSpan?>()), Times.Never);
        }

        [Test]
        public async Task VerifyAsync_WhenFifthFailure_ReturnsLockedAndSetsLock()
        {
            SeedValidCaptcha(Code);
            _redis.Setup(r => r.StringGetAsync(It.IsAny<string>()))
                .ReturnsAsync((string)null);
            _redis.Setup(r => r.StringIncrementAsync(It.IsAny<string>(), It.IsAny<int>(), It.IsAny<TimeSpan?>()))
                .ReturnsAsync(5L);

            var result = await _service.VerifyAsync("000000", Phone);

            Assert.That(result, Is.EqualTo(ErrCodeEnum.Verify_301003));
            _redis.Verify(r => r.StringSetAsync(
                    It.Is<string>(s => s.Contains("chk_fail:lock:13800138000")),
                    It.IsAny<string>(),
                    TimeSpan.FromHours(1)),
                Times.Once);
        }

        [Test]
        public async Task VerifyAsync_WhenCorrectCodeAndSetUsed_ConsumesAndReturnsSuccess()
        {
            SeedValidCaptcha(Code);
            _redis.Setup(r => r.StringGetAsync(It.IsAny<string>()))
                .ReturnsAsync((string)null);

            var result = await _service.VerifyAsync(Code, Phone);

            Assert.That(result, Is.EqualTo(ErrCodeEnum.Success));
            using var verify = new EsignDbContext(_dbOptions);
            var row = verify.VerificationCodeList.Single();
            Assert.That(row.Status, Is.EqualTo(CaptchaStatus.Used));
            _redis.Verify(r => r.StringSetAsync(
                    It.Is<string>(s => s.Contains("chk_fail:count:13800138000")),
                    "0",
                    TimeSpan.FromHours(1)),
                Times.Once);
        }

        [Test]
        public async Task VerifyAsync_WhenSetUsedFalse_DoesNotChangeStatus()
        {
            SeedValidCaptcha(Code);
            _redis.Setup(r => r.StringGetAsync(It.IsAny<string>()))
                .ReturnsAsync((string)null);

            var result = await _service.VerifyAsync(Code, Phone, setUsed: false);

            Assert.That(result, Is.EqualTo(ErrCodeEnum.Success));
            using var verify = new EsignDbContext(_dbOptions);
            var row = verify.VerificationCodeList.Single();
            Assert.That(row.Status, Is.EqualTo(CaptchaStatus.NotUsed));
        }

        private void SeedValidCaptcha(string code)
        {
            using var seed = new EsignDbContext(_dbOptions);
            seed.VerificationCodeList.Add(new VerificationCodeEntity
            {
                Id = Guid.NewGuid().ToString(),
                Code = code,
                Source = Source,
                Target = Phone,
                TargetType = CaptchaTarget.Phone,
                Status = CaptchaStatus.NotUsed,
                SendTime = DateTime.Now.AddMinutes(-1).ToLongUnixTimestamp(),
                ValidTime = DateTime.Now.AddMinutes(15).ToLongUnixTimestamp()
            });
            seed.SaveChanges();
        }
    }
}

