166	
167	            // 增加验证失败次数
168	            var failureCount =  await _redisClient.StringIncrementAsync(chkFailCountKey, 1, TimeSpan.FromHours(1));
169	
170	
171	            if (failureCount >= PHONE_CAPTCHA_CHK_FAIL_MAX_COUNT)
