private sealed class TestableCaptchaService : CaptchaService
{
    private readonly DbContextOptions<EsignDbContext> _options;

    public TestableCaptchaService(DbContextOptions<EsignDbContext> options, string dbName,
        ILoggerProvider loggerProvider,
        IOptions<SupplierOptions> optionAccessor, MsgAPI msgAPI, CaptchaApi captchaApi,
        IRedisClient redisClient, IHttpContextAccessor httpContextAccessor)
        : base(new EsignDbContext(options), loggerProvider, optionAccessor, msgAPI, captchaApi, redisClient, httpContextAccessor)
    {
        _options = new DbContextOptionsBuilder<EsignDbContext>()
            .UseInMemoryDatabase(dbName)
            .Options;
    }

    public int? ForceConsumeResult { get; set; }

    protected override async Task<int> MarkCaptchaUsedAsync(string captchaId, string code, string phone, long validTime)
    {
        if (ForceConsumeResult.HasValue)
        {
            return await Task.FromResult(ForceConsumeResult.Value);
        }

        using var db = new EsignDbContext(_options);
        var row = db.VerificationCodeList.FirstOrDefault(r =>
            r.Id == captchaId && r.Target == phone && r.Code == code &&
            r.Status == CaptchaStatus.NotUsed && r.ValidTime > validTime);
        if (row == null)
        {
            return 0;
        }
        row.Status = CaptchaStatus.Used;
        return await db.SaveChangesAsync();
    }
}

